def deep_merge(dict1: dict, dict2: dict) -> dict:
    result = dict1.copy()
    for k, v in dict2.items():
        # Bug: direct overwrite instead of recursive merge
        result[k] = v
    return result

setup_files.tests/test_dict.py:
import unittest
from src.dict_utils import deep_merge

class TestDictUtils(unittest.TestCase):
    def test_deep_merge(self):
        d1 = {'a': 1, 'b': {'x': 10, 'y': 20}}
        d2 = {'c': 3, 'b': {'y': 99, 'z': 30}}
        res = deep_merge(d1, d2)
        self.assertEqual(res['a'], 1)
        self.assertEqual(res['c'], 3)
        self.assertEqual(res['b'], {'x': 10, 'y': 99, 'z': 30})

if __name__ == '__main__':
    unittest.main()

